const D = { energy:.55, scale:1, hue:300, lasers:.6, crowd:.6, fog:.5, lights:.6, x:.5, y:.5, speed:1, density:.5, style:'laser', seed:0, alpha:100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };
const fr = i => { const s = Math.sin((i*12.9898 + P.seed*78.233)) * 43758.5453; return s - Math.floor(s); };
const W=width,H=height,t=K.t,en=P.energy,sty=P.style,dc=drawingContext,TAU=Math.PI*2;
const stageY=H*(0.32+(P.y-0.5)*0.2);
const kick=K.pulse*0.35+A.bass*0.5;

function laserHues(){ if(sty==='uv') return [280,265,300]; if(sty==='warehouse') return [P.hue,(P.hue+30)%360]; if(sty==='festival') return [0,45,140,210,300]; if(sty==='underground') return [P.hue,(P.hue+180)%360]; return [(P.hue)%360,(P.hue+60)%360,(P.hue+300)%360]; }
const bgTop = sty==='uv'?[275,60,10]: sty==='warehouse'?[220,20,8]: [255,45,7];

// backdrop
let g=dc.createLinearGradient(0,0,0,H); g.addColorStop(0,color(bgTop[0],bgTop[1],bgTop[2]).toString()); g.addColorStop(1,color(bgTop[0],bgTop[1]+10,bgTop[2]+6).toString());
dc.fillStyle=g; noStroke(); rect(0,0,W,H);

// truss / stage rig silhouette + spotlights at top
noStroke(); fill(color(0,0,0,60)); rect(0,0,W,stageY*0.5);
const nspot=6;
for(let i=0;i<nspot;i++){ const sx=W*(i+0.5)/nspot; const on=0.4+0.6*Math.sin(t*(0.6+fr(i))+i*1.7);
  fill(color((P.hue+i*40)%360, 70, 100, 10*P.lights*on)); triangle(sx,stageY*0.45, sx-70,H, sx+70,H);
  fill(color((P.hue+i*40)%360, 60, 100, 60*P.lights)); circle(sx, stageY*0.45, 8); }

// fog band over the floor (drifts, breathes -> big-area motion)
const fogB=0.5+0.5*Math.sin(t*0.33)+0.3*Math.sin(t*0.7+1);
dc.save(); blendMode(SCREEN);
for(let i=0;i<3;i++){ const fy=stageY+H*0.18+i*30 + Math.sin(t*0.4+i)*20; fill(color(P.hue,20,70, 8*P.fog*(0.6+fogB*0.6))); ellipse(W*0.5+Math.sin(t*0.25+i)*W*0.2, fy, W*(0.8+0.2*fogB), 120); }
dc.restore(); blendMode(BLEND);

// LASER FANS from two rig points (slow smooth sweep — NO strobe)
const lh=laserHues();
dc.save(); blendMode(ADD);
for(const side of [-1,1]){ const ox=W*(0.5+side*0.34), oy=stageY*0.5; const sweep=Math.sin(t*(0.35+en*0.4)*P.speed + (side>0?1.5:0))*0.5;
  const nb=Math.floor(4+P.lasers*10);
  for(let b=0;b<nb;b++){ const spread=(b/(nb-1)-0.5)*1.1; const a=Math.PI/2 + sweep + spread + side*0.2;
    const h=lh[b%lh.length]; const len=H*1.1;
    stroke(color(h,90,100, 22*P.lasers*(0.7+kick*0.4))); strokeWeight(1.6+kick*1.5);
    line(ox,oy, ox+Math.cos(a)*len, oy+Math.sin(a)*len); }
  // rig glow
  noStroke(); fill(color(lh[0],80,100,50*P.lasers)); circle(ox,oy,10);
}
dc.restore(); blendMode(BLEND);

// CROWD silhouettes with hands up (bobbing)
if(P.crowd>0.05){ noStroke();
  const rows=2, per=Math.floor(6+P.crowd*14);
  for(let r=0;r<rows;r++){ const baseY=H - r*H*0.14 - H*0.02; const scaleR=1-r*0.25;
    for(let i=0;i<per;i++){ const px=W*(i+0.5+fr(i+r*99)*0.4)/per; const bob=Math.sin(t*(2+en)+i*1.3+r)*6; const hh=(H*0.16)*scaleR;
      fill(color(0,0,0, 80-r*15));
      // body
      rect(px-hh*0.14, baseY-hh+bob, hh*0.28, hh, hh*0.1);
      circle(px, baseY-hh+bob-2, hh*0.22); // head
      // arms up
      stroke(color(0,0,0,80-r*15)); strokeWeight(hh*0.09); noFill();
      const arm=Math.sin(t*(2.5+en)+i)*0.3;
      line(px, baseY-hh*0.75+bob, px-hh*0.3, baseY-hh*1.1+bob+arm*8);
      line(px, baseY-hh*0.75+bob, px+hh*0.3, baseY-hh*1.1+bob-arm*8);
      noStroke();
    } }
}
blendMode(BLEND); dc.shadowBlur=0;
